public static int[][] extractRectangle(int h, int w, int[][] input) {
    if (input == null || w < 0 || h < 0 || h > input.length) {
        return null;
    }
    int[][] output = new int[h][w];
    for (int i = 0; i < h; i++) {
        // the row must be non-null and long enough
        if (input[i] == null || w > input[i].length) {
            return null;
        }
        for (int j = 0; j < w; j++) {
            output[i][j] = input[i][j];
        }
    }
    // none of the remaining rows may be null
    for (int i = h; i < input.length; i++) {
        if (input[i] == null) {
            return null;
        }
    }
    return output;
}
